00044 
00045 MatrixIntraPrediction::MatrixIntraPrediction():
00046   m_component(MAX_NUM_COMPONENT),
00047   m_reducedBoundary          (MIP_MAX_INPUT_SIZE),
00048   m_reducedBoundaryTransposed(MIP_MAX_INPUT_SIZE),
00049   m_inputOffset      ( 0 ),
00050   m_inputOffsetTransp( 0 ),
00051   m_refSamplesTop (MIP_MAX_WIDTH),
00052   m_refSamplesLeft(MIP_MAX_HEIGHT),
00053   m_blockSize( 0, 0 ),
00054   m_sizeId( 0 ),
00055   m_reducedBdrySize( 0 ),
00056   m_reducedPredSize( 0 ),
00057   m_upsmpFactorHor( 0 ),
00058   m_upsmpFactorVer( 0 )
00059 {
00060 }
00061 
00062 void MatrixIntraPrediction::prepareInputForPred(const CPelBuf &pSrc, const Area &block, const int bitDepth,
00063                                                 const ComponentID compId)
00064 {
00065   m_component = compId;
00066 
00067   // Step 1: Save block size and calculate dependent values
00068   initPredBlockParams(block);
00069 
00070   // Step 2: Get the input data (left and top reference samples)
00071   m_refSamplesTop.resize(block.width);
00072   for (int x = 0; x < block.width; x++)
00073   {
00074     m_refSamplesTop[x] = pSrc.at(x + 1, 0);
00075   }
00076 
00077   m_refSamplesLeft.resize(block.height);
00078   for (int y = 0; y < block.height; y++)
00079   {
00080     m_refSamplesLeft[y] = pSrc.at(y + 1, 1);
00081   }
00082 
00083   // Step 3: Compute the reduced boundary via Haar-downsampling (input for the prediction)
00084   const int inputSize = 2 * m_reducedBdrySize;
00085   m_reducedBoundary          .resize( inputSize );
00086   m_reducedBoundaryTransposed.resize( inputSize );
00087 
00088   int* const topReduced = m_reducedBoundary.data();
00089   boundaryDownsampling1D( topReduced, m_refSamplesTop.data(), block.width, m_reducedBdrySize );
00090 
00091   int* const leftReduced = m_reducedBoundary.data() + m_reducedBdrySize;
00092   boundaryDownsampling1D( leftReduced, m_refSamplesLeft.data(), block.height, m_reducedBdrySize );
00093 
00094   int* const leftReducedTransposed = m_reducedBoundaryTransposed.data();
00095   int* const topReducedTransposed  = m_reducedBoundaryTransposed.data() + m_reducedBdrySize;
00096   for( int x = 0; x < m_reducedBdrySize; x++ )
00097   {
00098     topReducedTransposed[x] = topReduced[x];
00099   }
00100   for( int y = 0; y < m_reducedBdrySize; y++ )
00101   {
00102     leftReducedTransposed[y] = leftReduced[y];
00103   }
00104 
00105   // Step 4: Rebase the reduced boundary
00106 
00107   m_inputOffset       = m_reducedBoundary[0];
00108   m_inputOffsetTransp = m_reducedBoundaryTransposed[0];
00109 
00110   const bool hasFirstCol = (m_sizeId < 2);
00111   m_reducedBoundary          [0] = hasFirstCol ? ((1 << (bitDepth - 1)) - m_inputOffset      ) : 0; // first column of matrix not needed for large blocks
00112   m_reducedBoundaryTransposed[0] = hasFirstCol ? ((1 << (bitDepth - 1)) - m_inputOffsetTransp) : 0;
00113   for (int i = 1; i < inputSize; i++)
00114   {
00115     m_reducedBoundary          [i] -= m_inputOffset;
00116     m_reducedBoundaryTransposed[i] -= m_inputOffsetTransp;
00117   }
00118 }
00119 
00120 void MatrixIntraPrediction::predBlock(int *const result, const int modeIdx, const bool transpose, const int bitDepth,
00121                                       const ComponentID compId)
00122 {
00123   CHECK(m_component != compId, "Boundary has not been prepared for this component.");
00124 
00125   const bool needUpsampling = ( m_upsmpFactorHor > 1 ) || ( m_upsmpFactorVer > 1 );
00126 
00127   const uint8_t* matrix = getMatrixData(modeIdx);
00128 
00129   static_vector<int, MIP_MAX_REDUCED_OUTPUT_SAMPLES> bufReducedPred( m_reducedPredSize * m_reducedPredSize );
00130   int* const       reducedPred     = needUpsampling ? bufReducedPred.data() : result;
00131   const int* const reducedBoundary = transpose ? m_reducedBoundaryTransposed.data() : m_reducedBoundary.data();
00132   computeReducedPred(reducedPred, reducedBoundary, matrix, transpose, bitDepth);
00133   if( needUpsampling )
00134   {
00135     predictionUpsampling( result, reducedPred );
00136   }
00137 }
00138 
00139 
00140 void MatrixIntraPrediction::initPredBlockParams(const Size& block)
00141 {
00142   m_blockSize = block;
00143   // init size index
00144   m_sizeId = getMipSizeId( m_blockSize );
00145 
00146   // init reduced boundary size
00147   m_reducedBdrySize = (m_sizeId == 0) ? 2 : 4;
00148 
00149   // init reduced prediction size
00150   m_reducedPredSize = ( m_sizeId < 2 ) ? 4 : 8;
00151 
00152 
00153   // init upsampling factors
00154   m_upsmpFactorHor = m_blockSize.width  / m_reducedPredSize;
00155   m_upsmpFactorVer = m_blockSize.height / m_reducedPredSize;
00156 
00157   CHECKD( (m_upsmpFactorHor < 1) || ((m_upsmpFactorHor & (m_upsmpFactorHor - 1)) != 0), "Need power of two horizontal upsampling factor." );
00158   CHECKD( (m_upsmpFactorVer < 1) || ((m_upsmpFactorVer & (m_upsmpFactorVer - 1)) != 0), "Need power of two vertical upsampling factor." );
00159 }
00160 
00161 
00162 
00163 void MatrixIntraPrediction::boundaryDownsampling1D(int* reducedDst, const int* const fullSrc, const SizeType srcLen, const SizeType dstLen)
00164 {
00165   if (dstLen < srcLen)
00166   {
00167     // Create reduced boundary by downsampling
00168     const SizeType downsmpFactor = srcLen / dstLen;
00169     const int log2DownsmpFactor = floorLog2(downsmpFactor);
00170     const int roundingOffset = (1 << (log2DownsmpFactor - 1));
00171 
00172     SizeType srcIdx = 0;
00173     for( SizeType dstIdx = 0; dstIdx < dstLen; dstIdx++ )
00174     {
00175       int sum = 0;
00176       for( int k = 0; k < downsmpFactor; k++ )
00177       {
00178         sum += fullSrc[srcIdx++];
00179       }
00180       reducedDst[dstIdx] = (sum + roundingOffset) >> log2DownsmpFactor;
00181     }
00182   }
00183   else
00184   {
00185     // Copy boundary if no downsampling is needed
00186     for (SizeType i = 0; i < dstLen; ++i)
00187     {
00188       reducedDst[i] = fullSrc[i];
00189     }
00190   }
00191 }
00192 
00193 
00194 void MatrixIntraPrediction::predictionUpsampling1D(int* const dst, const int* const src, const int* const bndry,
00195                                                    const SizeType srcSizeUpsmpDim, const SizeType srcSizeOrthDim,
00196                                                    const SizeType srcStep, const SizeType srcStride,
00197                                                    const SizeType dstStep, const SizeType dstStride,
00198                                                    const SizeType bndryStep,
00199                                                    const unsigned int upsmpFactor )
00200 {
00201   const int log2UpsmpFactor = floorLog2( upsmpFactor );
00202   CHECKD( upsmpFactor <= 1, "Upsampling factor must be at least 2." );
00203   const int roundingOffset = 1 << (log2UpsmpFactor - 1);
00204 
00205   SizeType idxOrthDim = 0;
00206   const int* srcLine = src;
00207   int* dstLine = dst;
00208   const int* bndryLine = bndry + bndryStep - 1;
00209   while( idxOrthDim < srcSizeOrthDim )
00210   {
00211     SizeType idxUpsmpDim = 0;
00212     const int* before = bndryLine;
00213     const int* behind = srcLine;
00214     int* currDst = dstLine;
00215     while( idxUpsmpDim < srcSizeUpsmpDim )
00216     {
00217       SizeType pos = 1;
00218       int scaledBefore = ( *before ) << log2UpsmpFactor;
00219       int scaledBehind = 0;
00220       while( pos <= upsmpFactor )
00221       {
00222         scaledBefore -= *before;
00223         scaledBehind += *behind;
00224         *currDst = (scaledBefore + scaledBehind + roundingOffset) >> log2UpsmpFactor;
00225 
00226         pos++;
00227         currDst += dstStep;
00228       }
00229 
00230       idxUpsmpDim++;
00231       before = behind;
00232       behind += srcStep;
00233     }
00234 
00235     idxOrthDim++;
00236     srcLine += srcStride;
00237     dstLine += dstStride;
00238     bndryLine += bndryStep;
00239   }
00240 }
00241 
00242 
00243 void MatrixIntraPrediction::predictionUpsampling( int* const dst, const int* const src ) const
00244 {
00245   const int* verSrc     = src;
00246   SizeType   verSrcStep = m_blockSize.width;
00247 
00248   if( m_upsmpFactorHor > 1 )
00249   {
00250     int* const horDst = dst + (m_upsmpFactorVer - 1) * m_blockSize.width;
00251     verSrc = horDst;
00252     verSrcStep *= m_upsmpFactorVer;
00253 
00254     predictionUpsampling1D( horDst, src, m_refSamplesLeft.data(),
00255                             m_reducedPredSize, m_reducedPredSize,
00256                             1, m_reducedPredSize, 1, verSrcStep,
00257                             m_upsmpFactorVer, m_upsmpFactorHor );
00258   }
00259 
00260   if( m_upsmpFactorVer > 1 )
00261   {
00262     predictionUpsampling1D( dst, verSrc, m_refSamplesTop.data(),
00263                             m_reducedPredSize, m_blockSize.width,
00264                             verSrcStep, 1, m_blockSize.width, 1,
00265                             1, m_upsmpFactorVer );
00266   }
00267 }
00268 
00269 const uint8_t* MatrixIntraPrediction::getMatrixData(const int modeIdx) const
00270 {
00271   switch( m_sizeId )
00272   {
00273   case 0: return &mipMatrix4x4[modeIdx][0][0];
00274 
00275   case 1: return &mipMatrix8x8[modeIdx][0][0];
00276 
00277   case 2: return &mipMatrix16x16[modeIdx][0][0];
00278 
00279   default: THROW( "Invalid mipSizeId" );
00280   }
00281 }
00282 
00283 void MatrixIntraPrediction::computeReducedPred( int*const result, const int* const input,
00284                                                 const uint8_t* matrix,
00285                                                 const bool transpose, const int bitDepth )
00286 {
00287   const int inputSize = 2 * m_reducedBdrySize;
00288 
00289   // use local buffer for transposed result
00290   static_vector<int, MIP_MAX_REDUCED_OUTPUT_SAMPLES> resBufTransposed( m_reducedPredSize * m_reducedPredSize );
00291   int*const resPtr = (transpose) ? resBufTransposed.data() : result;
00292 
00293   int sum = 0;
00294   for( int i = 0; i < inputSize; i++ ) { sum += input[i]; }
00295   const int offset = (1 << (MIP_SHIFT_MATRIX - 1)) - MIP_OFFSET_MATRIX * sum;
00296   CHECK( inputSize != 4 * (inputSize >> 2), "Error, input size not divisible by four" );
00297 
00298   const uint8_t *weight = matrix;
00299   const int   inputOffset = transpose ? m_inputOffsetTransp : m_inputOffset;
00300 
00301   const bool redSize = (m_sizeId == 2);
00302   int posRes = 0;
00303   for( int y = 0; y < m_reducedPredSize; y++ )
00304   {
00305     for( int x = 0; x < m_reducedPredSize; x++ )
00306     {
00307       if( redSize ) weight -= 1;
00308       int tmp0 = redSize ? 0 : (input[0] * weight[0]);
00309       int tmp1 = input[1] * weight[1];
00310       int tmp2 = input[2] * weight[2];
00311       int tmp3 = input[3] * weight[3];
00312       for (int i = 4; i < inputSize; i += 4)
00313       {
00314         tmp0 += input[i]     * weight[i];
00315         tmp1 += input[i + 1] * weight[i + 1];
00316         tmp2 += input[i + 2] * weight[i + 2];
00317         tmp3 += input[i + 3] * weight[i + 3];
00318       }
00319       resPtr[posRes++] = ClipBD<int>(((tmp0 + tmp1 + tmp2 + tmp3 + offset) >> MIP_SHIFT_MATRIX) + inputOffset, bitDepth);
00320 
00321       weight += inputSize;
00322     }
00323   }
00324 
00325   if( transpose )
00326   {
00327     for( int y = 0; y < m_reducedPredSize; y++ )
00328     {
00329       for( int x = 0; x < m_reducedPredSize; x++ )
00330       {
00331         result[ y * m_reducedPredSize + x ] = resPtr[ x * m_reducedPredSize + y ];
00332       }
00333     }
00334   }
00335 }
